begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select is((select count(*)::int from private.provider_runtime_config where provider in ('openai','gpt-6-astra','gpt-6.1-sol')and enabled=false),3,'OpenAI models start disabled');
select ok(not exists(select 1 from private.credit_price_versions v cross join lateral jsonb_array_elements(v.prices)p where p->>'provider' in ('openai','gpt-6-astra','gpt-6.1-sol')),'no OpenAI production price is invented');
select ok(not has_function_privilege('authenticated','public.credit_admin(jsonb)','execute'),'browser cannot enable provider prices');
select ok(not has_function_privilege('service_role','public.credit_admin_before_openai(jsonb)','execute'),'old administrator bypass is private');
insert into auth.users(id,email,email_confirmed_at,is_anonymous)values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','openai-offline@example.com',now(),false);
create function pg_temp.openai_submit(model text,cfg jsonb,req text)returns jsonb language sql as $$select private.submit_image_generation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',null,'Offline test','openai',model,cfg,'direct',null,null,null,req,req,gen_random_uuid())$$;
select throws_ok($$select pg_temp.openai_submit('gpt-image-2.6-flare','{"count":1,"aspectRatio":"1:1","resolution":"2K"}','bad-res')$$,'22023','image_model_upgrade_required','OpenAI cannot silently use an unpriced resolution');
select throws_ok($$select pg_temp.openai_submit('gpt-image-unknown','{"count":1,"aspectRatio":"1:1","resolution":"1K"}','bad-model')$$,'22023','image_model_upgrade_required','OpenAI cannot admit arbitrary model aliases');
select throws_ok($$select pg_temp.openai_submit('gpt-image-2.6-flare','{"count":1,"aspectRatio":"1:1","resolution":"1K","targetWidth":970,"targetHeight":600}','bad-target')$$,'22023','image_model_upgrade_required','unsupported commerce export geometry cannot be billed as square');
select throws_ok($$select pg_temp.openai_submit('gpt-image-2.6-flare','{"count":1,"aspectRatio":"1:1","resolution":"1K"}','disabled')$$,'P0001','provider_unavailable','disabled runtime prevents a new paid image');
update private.provider_runtime_config set enabled=true where provider='openai';
update private.runtime_flags set enabled=true where flag='generation_enabled';
select lives_ok($$select pg_temp.openai_submit('gpt-image-2.6-flare','{"count":1,"aspectRatio":"1:1","resolution":"1K","referenceIds":[]}','valid-flare')$$,'explicit square Images API identity is admitted by the private function');
select lives_ok($$select pg_temp.openai_submit('gpt-image-2.6-sunburst','{"count":1,"aspectRatio":"1:1","resolution":"1K","referenceIds":[]}','valid-sunburst')$$,'second image model has its own durable identity');
select is((select count(*)::int from public.generation_batches where user_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),2,'both models retain separate original batch identities');
select finish();
rollback;
